from inventory.codes import next_warehouse_code, warehouse_code_prefix



def fill_warehouse_codes(apps, schema_editor):
    """Existing warehouses get their code (state or country + number), oldest first."""
    Warehouse = apps.get_model("inventory", "Warehouse")
    taken: set[str] = set()
    for warehouse in Warehouse.objects.order_by("id"):
        code = next_warehouse_code(warehouse_code_prefix(warehouse.state, warehouse.country), taken)
        taken.add(code)
        warehouse.code = code
        warehouse.save(update_fields=["code"])


def create_transit_location(apps, schema_editor):
    """The global virtual location of assets travelling between warehouses."""
    Location = apps.get_model("inventory", "Location")
    Location.objects.get_or_create(
        code="VIRTUAL-TRANSIT",
        defaults={"segment": "TRANSIT", "area_type": "virtual_transit"},
    )


